const basic = () => 'Basic ' + Buffer.from(`${process.env.NOTION_OAUTH_CLIENT_ID}:${process.env.NOTION_OAUTH_CLIENT_SECRET}`).toString('base64');

async function notionToken(body: Record<string, string>) {
  const res = await fetch('https://api.notion.com/v1/oauth/token', {
    method: 'POST',
    headers: { Authorization: basic(), 'Content-Type': 'application/json', 'Notion-Version': process.env.NOTION_VERSION ?? '2026-03-11' },
    body: JSON.stringify(body),
  });
  const json = await res.json();
  if (!res.ok) throw Object.assign(new Error(json.error ?? 'notion_oauth_error'), { status: res.status, body: json });
  return json as { access_token: string; refresh_token: string; bot_id: string; workspace_id: string; workspace_name?: string; owner: unknown };
}

export const exchangeCode = (code: string) =>
  notionToken({ grant_type: 'authorization_code', code, redirect_uri: process.env.NOTION_REDIRECT_URI! });

// Call inside a per-connection lock (e.g. SELECT ... FOR UPDATE) and save BOTH tokens in the same transaction.
export const refresh = (refreshToken: string) =>
  notionToken({ grant_type: 'refresh_token', refresh_token: refreshToken });
